#!/usr/bin/env bash
# Builds Atmosphère with USB Loader NX (the fork in atmosphere/, compiling src/) and the Manager in the atms-build-libnx image.
# Version: USBL_VERSION, else the closest v* tag of master (git describe), else "dev".
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
TARGET="${1:-all}"
VERSION="${USBL_VERSION:-$(git -C "$ROOT" describe --tags --match 'v*' --dirty 2>/dev/null || echo dev)}"

cat > "$ROOT/common/include/usbl/version.hpp" <<HEADER
#pragma once
/* Generated by scripts/build.sh. */
namespace usbl {
    constexpr char Version[] = "$VERSION";
}
HEADER

# Runs as the calling user so the output belongs to it (on CI the runner's uid is not the image's).
run() { docker run --rm -u "$(id -u):$(id -g)" -e HOME=/tmp -v "$ROOT":/work -w "/work/$1" atms-build-libnx sh -c "git config --global --add safe.directory '*'; $2"; }

echo "USB Loader NX $VERSION"
if [[ "$TARGET" == "all" || "$TARGET" == "atmosphere" ]]; then
    # haze's makefile links the .nro in parallel with generating its romfs shaders; on a clean tree that races.
    run atmosphere 'make -j1 -C troposphere/haze && make -j$(nproc) dist-no-debug-nx_release ATMOSPHERE_GIT_BRANCH=usb-loader-nx'
fi
# The Manager joins the repository once its new design is in; until then it may be missing.
if [[ ( "$TARGET" == "all" || "$TARGET" == "manager" ) && -f "$ROOT/manager/Makefile" ]]; then
    run manager "make -C lib/Plutonium/Plutonium -j\$(nproc) && make -j\$(nproc) APP_VERSION=${VERSION#v}"
fi
